append.value:
CREATE PARTITION FUNCTION [Hashing_partition] (TINYINT) AS RANGE LEFT FOR VALUES (0, 1, 2, 3, 4, 5, 6, 7);

  CREATE PARTITION SCHEME [ps_Hashing_partition] AS PARTITION [Hashing_partition] ALL TO ('PRIMARY');

  ALTER TABLE [TB_ASMI_CS_NONCEDETAILS]
    ADD [HASH_VALUE] AS (CONVERT([tinyint], abs(binary_checksum([DEVICE_ID])%(12)),(0)))
    PERSISTED NOT NULL;

  CREATE CLUSTERED INDEX [TB_ASMI_CS_NONCEDETAILS_INDEX_1]
    ON [TB_ASMI_CS_NONCEDETAILS]
    ([DEVICE_ID] ASC, [HASH_VALUE])
    ON ps_Hashing_partition(HASH_VALUE);

  create unique index TB_ASMI_CS_NONCEDETAILS_IDX01 on TB_ASMI_CS_NONCEDETAILS(DEVICE_ID, APP_ID, REQUEST_ID, CLIENT_NONCE, SERVER_NONCE,CREATED_ON, HASH_VALUE);
